#include <stdint.h>
#include <stddef.h>

void reverse(int *arr, int n) {
    if (!arr || n < 2) return;
    size_t lo = 0;
    size_t hi = n - 1;
    while (lo < hi) {
        int tmp = arr[lo];
        arr[lo] = arr[hi];
        arr[hi] = tmp;
        ++lo;
        --hi;
    }
}
